#!/usr/bin/env python3
"""Entanglement/Crofton interpretation of the interval-space wave curvature."""
import json,sys,math
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2];sys.path.insert(0,str(ROOT/'research/benincasa/.tmp_sympy'));import sympy as s
u,v,c,eps=s.symbols('u v c eps',positive=True);S=c/s.Integer(3)*s.log((v-u)/eps);h=s.simplify(s.diff(S,u,v));metric_factor=s.simplify(12*h/c);rows=[]
for L in range(1,51):
 cmi=math.log((L+1)**2/(L*(L+2)));rows.append({'length':L,'conditional_mutual_information':cmi,'positive':cmi>0,'L2_scaled':L*L*cmi})
checks={'crofton_hessian_is_inverse_square':s.simplify(h-c/(3*(v-u)**2))==0,'desitter_metric_is_entropy_hessian':s.simplify(metric_factor-4/(v-u)**2)==0,'discrete_cmi_positive':all(x['positive'] for x in rows),'discrete_cmi_formula_is_strong_subadditivity':all(abs(x['conditional_mutual_information']-math.log((x['length']+1)**2/(x['length']*(x['length']+2))))<1e-15 for x in rows),'large_interval_curvature_scales_inverse_square':abs(rows[-1]['L2_scaled']-1)<.04}
out={'schema':'marici.nima.nnmhv-entanglement-crofton-bridge.v1','continuum':{'interval_entropy':'S(u,v)=(c/3) log((v-u)/epsilon)','crofton_form':'partial_u partial_v S du dv = c/[3(v-u)^2] du dv','desitter_metric':'ds^2=(12/c) partial_u partial_v S du dv'},'discrete':{'entropy':'S_L=log L','positive_plaquette':'I_L=2 S_(L+1)-S_L-S_(L+2)=log((L+1)^2/[L(L+2)])','relation_to_mobius':'I_L = -Box_d S_L','asymptotic':'I_L ~ L^-2'},'checks':checks,'passed':all(checks.values()),'meaning':'The projective de Sitter metric is the Crofton/information metric generated by interval entropy. The sign-reversed Möbius wave curvature is positive conditional mutual information, so local history curvature is an information-theoretic strong-subadditivity defect.','bridges':['CFT interval entanglement entropy','Crofton geometry and kinematic space','conditional mutual information','strong subadditivity','information geometry','inverse-square completion curvature']};p=ROOT/'research/nima/results/nnmhv-entanglement-crofton-bridge.json';p.write_text(json.dumps(out,indent=2)+'\n');print(json.dumps({'schema':out['schema'],'continuum':out['continuum'],'discrete':out['discrete'],'checks':checks,'meaning':out['meaning'],'bridges':out['bridges'],'passed':out['passed']},indent=2));raise SystemExit(0 if out['passed'] else 1)
